<?php if($errors->any()): ?><div class="alert alert-danger"><ul class="mb-0"><?php $__currentLoopData = $errors->all(); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $error): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><li><?php echo e($error); ?></li><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></ul></div><?php endif; ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Servicio</label><select class="form-select" name="servicio_id" required><option value="">Seleccione</option><?php $__currentLoopData = $servicios; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $servicio): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($servicio->id); ?>" <?php if(old('servicio_id',$pago->servicio_id??'')==$servicio->id): echo 'selected'; endif; ?>>#<?php echo e($servicio->id); ?> · <?php echo e($servicio->cliente?->nombres); ?> · <?php echo e($servicio->origen); ?> → <?php echo e($servicio->destino); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="col-md-6"><label class="form-label">Método de pago</label><select class="form-select" name="metodo_pago"><?php $__currentLoopData = ['Efectivo','Transferencia','Tarjeta']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $metodo): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(old('metodo_pago',$pago->metodo_pago??'Efectivo')===$metodo): echo 'selected'; endif; ?>><?php echo e($metodo); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="col-md-6"><label class="form-label">Monto</label><input type="number" step="0.01" min="0" class="form-control" name="monto" value="<?php echo e(old('monto',$pago->monto??'')); ?>" required></div><div class="col-md-6"><label class="form-label">Fecha de pago</label><input type="date" class="form-control" name="fecha_pago" value="<?php echo e(old('fecha_pago',isset($pago)?optional($pago->fecha_pago)->format('Y-m-d'):date('Y-m-d'))); ?>" required></div></div><div class="mt-4"><button class="btn btn-success">Guardar</button><a class="btn btn-secondary" href="<?php echo e(route('pagos.index')); ?>">Cancelar</a></div>
